		/** 
		 * Tests creating a new Tenant.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Tenant");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Tenant" );

			try {            
				Tenant entity = TenantService.getTenantInstance().createTenant( generateNewEntity() );
				thePrimaryKey = entity.getTenantId();
				LOGGER.info( "-- Successfully created a Tenant with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Tenant. 
		 */
		public Tenant testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Tenant" );

			Tenant entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Tenant with primary key" );
			msg.append( thePrimaryKey );
			
			TenantFetchOneSummary fetchOneSummary = new TenantFetchOneSummary( thePrimaryKey );

			try {
				entity = TenantService.getTenantInstance().getTenant( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Tenant " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Tenant.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Tenant." );

			StringBuilder msg = new StringBuilder( "Failed to update a Tenant : " );        
			Tenant entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Tenant." );

				// for use later on...
				thePrimaryKey = entity.getTenantId();

				TenantService proxy = TenantService.getTenantInstance();            
				proxy.updateTenant( entity );   

				LOGGER.info( "-- Successfully saved Tenant - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Tenant.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Tenant." );

			try{
			    Tenant entity = testRead(); 
				TenantService.getTenantInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Tenant with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Tenant with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Tenants.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Tenants:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Tenant : " );        
			List<Tenant> collection  = null;

			try {
				// call the static get method on the TenantService
				collection = TenantService.getTenantInstance().getAllTenant();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Tenant entity = null;            
					Iterator<Tenant> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getTenantId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

